begin;
create extension if not exists pgtap with schema extensions;
select extensions.no_plan();
insert into auth.users(id) select ('4c000000-0000-4000-8000-00000000000'||n)::uuid from generate_series(1,6)n;
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) select id,id,'totp','verified',now(),now() from auth.users where id::text like '4c000000-%';
insert into auth.sessions(id,user_id,factor_id,aal) select id,id,id,'aal2' from auth.users where id::text like '4c000000-%';
insert into public.team_profiles(id,full_name,is_active) select id,'Synthetic product staff',id::text not like '%5' from auth.users where id::text like '4c000000-%';
insert into public.team_role_assignments select ('4c000000-0000-4000-8000-00000000000'||v.n)::uuid,r.id from (values(1,'platform_owner'),(2,'technical_lead'),(3,'content_community_lead'),(4,'operations_lead'),(5,'platform_owner'))v(n,code)join public.roles r on r.code=v.code;
create function pg_temp.claims(n integer,assurance text default 'aal2') returns text language sql as $$select json_build_object('sub','4c000000-0000-4000-8000-00000000000'||n,'role','authenticated','aal',assurance,'session_id','4c000000-0000-4000-8000-00000000000'||n,'exp',extract(epoch from now()+interval '1 hour')::bigint)::text$$;
create temp table target(id uuid);grant all on target to authenticated,service_role;
create function pg_temp.h(v text) returns text language sql immutable as $$select encode(sha256(convert_to(v,'UTF8')),'hex')$$;
create function pg_temp.join_waitlist(k text,mail text default 'one@example.invalid',person text default 'Synthetic Person',consent boolean default true) returns void language sql as $$select public.submit_product_waitlist(jsonb_build_object('productId',(select id from target),'fullName',person,'email',mail,'whatsapp',null,'consent',consent,'consentVersion','product-updates-v1'),pg_temp.h('identity:'||mail),pg_temp.h('key:'||k),pg_temp.h('payload:'||person||mail),pg_temp.h('withdraw:'||mail),pg_temp.h('global-products-fixture'),pg_temp.h('email:'||mail),pg_temp.h('product-fixture'))$$;
select extensions.is((select count(*) from public.permissions),37::bigint,'two reviewed product permissions added');
select extensions.is((select count(*) from public.role_permissions),73::bigint,'three precise product mappings');
select extensions.ok(not has_table_privilege('anon','business_private.products','select'),'anonymous cannot read canonical drafts');
select extensions.ok(not has_table_privilege('authenticated','business_private.product_waitlist_entries','SELECT,INSERT,UPDATE,DELETE'),'ordinary direct subscriber access denied');
select extensions.ok(not has_function_privilege('anon','public.submit_product_waitlist(jsonb,text,text,text,text,text,text,text)','execute'),'anonymous cannot bypass trusted ingress');
select extensions.ok(not has_function_privilege('service_role','public.save_product_identity(uuid,integer,text,text,text,text)','execute'),'ingress cannot edit product identities');
set local role authenticated;select set_config('request.jwt.claims',pg_temp.claims(1,'aal1'),true);
select extensions.throws_ok($$select public.list_staff_products()$$,'42501',null,'AAL1 staff denied');
select set_config('request.jwt.claims',pg_temp.claims(6),true);
select extensions.throws_ok($$select public.list_staff_products()$$,'42501',null,'unassigned AAL2 denied');
select set_config('request.jwt.claims',pg_temp.claims(5),true);
select extensions.throws_ok($$select public.list_staff_products()$$,'42501',null,'inactive Owner denied');
select set_config('request.jwt.claims',pg_temp.claims(3),true);
select extensions.throws_ok($$select public.save_product_identity(null,0,'Unapproved concept','unapproved-concept','Test',null)$$,'42501',null,'Content cannot create unapproved product identities');
select set_config('request.jwt.claims',pg_temp.claims(1),true);
insert into target select (public.save_product_identity(null,0,'Fixture Product','product-fixture','Innovation',null)->>'id')::uuid;
select extensions.is(public.get_staff_product((select id from target))->>'publication','draft','creation remains unpublished');
select extensions.is(public.get_published_product('product-fixture'),null::jsonb,'draft has no public projection');
select extensions.throws_ok($$select public.publish_product((select id from target),1,'published','public')$$,'22023',null,'incomplete descriptions cannot publish');
select extensions.lives_ok($$select public.save_product_copy((select id from target),1,'A short description','Approved public details','["Creator discovery"]',null,'{}')$$,'Owner edits approved presentation');
select set_config('request.jwt.claims',pg_temp.claims(2),true);
select extensions.lives_ok($$select public.set_product_technical((select id from target),2,'in_development','Confidential engineering review')$$,'Technology edits technical status');
select extensions.is(public.get_staff_product((select id from target))->>'publication','draft','technical transition never publishes');
select extensions.throws_ok($$select public.publish_product((select id from target),3,'published','public')$$,'42501',null,'Technology cannot publish');
select extensions.throws_ok($$select public.list_product_waitlist((select id from target))$$,'42501',null,'Technology cannot see subscribers');
select set_config('request.jwt.claims',pg_temp.claims(3),true);
select extensions.ok(not (public.get_staff_product((select id from target)) ? 'technicalSummary'),'Content does not see technical review');
select extensions.ok(not (public.get_staff_product((select id from target)) ? 'subscriberCount'),'Content does not see subscriber counts');
select extensions.throws_ok($$select public.set_product_technical((select id from target),3,'launched','')$$,'42501',null,'Content cannot declare engineering status');
select extensions.lives_ok($$select public.publish_product((select id from target),3,'published','public')$$,'authorized Content explicitly publishes');
select extensions.is(public.get_published_product('product-fixture')->>'developmentStatus','in_development','public development status remains independent');
select extensions.throws_ok($$select public.save_product_copy((select id from target),4,'','','[]',null,'{}')$$,'22023',null,'published descriptions cannot silently become empty');
select extensions.ok(public.get_published_product('product-fixture')::text not like '%Confidential engineering%' and not (public.get_published_product('product-fixture') ? 'subscriberCount'),'public projection omits technical and subscriber data');
select extensions.throws_ok($$select public.set_product_waitlist((select id from target),4,true)$$,'42501',null,'Content cannot enable waitlist');
select set_config('request.jwt.claims',pg_temp.claims(4),true);
select extensions.ok(not (public.get_staff_product((select id from target)) ? 'description'),'Operations receives operational projection only');
select extensions.lives_ok($$select public.set_product_waitlist((select id from target),4,true)$$,'Operations enables individual product waitlist');
select extensions.throws_ok($$select public.set_product_waitlist((select id from target),4,false)$$,'PT409',null,'stale setting update rejected');
reset role;set local role service_role;
select extensions.throws_ok($$select pg_temp.join_waitlist('missing-consent','one@example.invalid','Synthetic Person',false)$$,'22023',null,'consent mandatory independently in SQL');
select extensions.lives_ok($$select pg_temp.join_waitlist('first')$$,'trusted anonymous ingress records registration');
select extensions.lives_ok($$select pg_temp.join_waitlist('first')$$,'same intent replay accepted');
select extensions.lives_ok($$select pg_temp.join_waitlist('duplicate','one@example.invalid','Attacker replacement')$$,'duplicate email gets no update or membership disclosure');
select extensions.throws_ok($$select pg_temp.join_waitlist('fourth')$$,'P0001',null,'per-email shared quota enforced');
reset role;
select extensions.is((select count(*) from business_private.product_waitlist_entries where product_id=(select id from target)),1::bigint,'one row after repeated submissions');
select extensions.is((select full_name from business_private.product_waitlist_entries where product_id=(select id from target)),'Synthetic Person','duplicate does not replace original identity details');
select extensions.is((select count(*) from public.audit_logs where action='waitlist.joined' and resource_id in(select id::text from business_private.product_waitlist_entries where product_id=(select id from target))),1::bigint,'one consent audit for actual insert');
set local role authenticated;select set_config('request.jwt.claims',pg_temp.claims(3),true);
select extensions.throws_ok($$select public.list_product_waitlist((select id from target))$$,'42501',null,'Content cannot read registrations despite publishing');
select set_config('request.jwt.claims',pg_temp.claims(4),true);
select extensions.is(jsonb_array_length(public.list_product_waitlist((select id from target))),1,'authorized Operations reads subscriber');
select extensions.ok(public.list_product_waitlist((select id from target))::text not like '%withdrawal_hash%' and public.list_product_waitlist((select id from target))::text not like '%identity_hash%','staff response omits credential and identity hashes');
reset role;set local role service_role;
select extensions.lives_ok($$select public.withdraw_product_waitlist(pg_temp.h('withdraw:one@example.invalid'),pg_temp.h('withdraw-global'),pg_temp.h('withdraw-budget-one'))$$,'private capability withdrawal accepted');
select extensions.lives_ok($$select public.withdraw_product_waitlist(pg_temp.h('withdraw:one@example.invalid'),pg_temp.h('withdraw-global'),pg_temp.h('withdraw-budget-one'))$$,'withdrawal replay is a generic no-op');
reset role;
select extensions.ok((select full_name is null and email is null and whatsapp is null and withdrawal_hash is null and status='withdrawn' from business_private.product_waitlist_entries where product_id=(select id from target)),'withdrawal erases contact and usable token');
select extensions.is((select count(*) from public.audit_logs where action='waitlist.withdrawn' and resource_id in(select id::text from business_private.product_waitlist_entries where product_id=(select id from target))),1::bigint,'withdrawal audit not duplicated');
set local role service_role;
select pg_temp.join_waitlist('second-entry','two@example.invalid');
select extensions.throws_ok($$select pg_temp.join_waitlist('second-entry','two@example.invalid','Changed payload')$$,'22023',null,'idempotency key cannot change submitted details');
select public.withdraw_product_waitlist(pg_temp.h('withdraw:two@example.invalid'),pg_temp.h('withdraw-global'),pg_temp.h('withdraw-budget-two'));
select extensions.lives_ok($$select pg_temp.join_waitlist('reconsent-attempt','two@example.invalid','Replace withdrawn person')$$,'withdrawn identity receives generic duplicate behavior');
reset role;
select extensions.is((select count(*) from business_private.product_waitlist_entries where product_id=(select id from target) and status='active'),0::bigint,'anonymous duplicate cannot opt a withdrawn person back in');
set local role authenticated;select set_config('request.jwt.claims',pg_temp.claims(3),true);
select public.publish_product((select id from target),5,'published','private');
select extensions.is(public.get_published_product('product-fixture'),null::jsonb,'private visibility hides a published product');
reset role;set local role service_role;
select extensions.throws_ok($$select pg_temp.join_waitlist('closed','three@example.invalid')$$,'22023',null,'old open form cannot join a private product');
select extensions.lives_ok($$select public.withdraw_product_waitlist(pg_temp.h('unknown-capability'),pg_temp.h('withdraw-global'),pg_temp.h('withdraw-budget-unknown'))$$,'withdrawal remains available after product closes');
reset role;set local role authenticated;select set_config('request.jwt.claims',pg_temp.claims(3),true);
select public.publish_product((select id from target),6,'published','public');
reset role;
create function pg_temp.fail_waitlist_audit() returns trigger language plpgsql as $$begin if new.action='waitlist.joined' then raise exception 'Synthetic audit rollback';end if;return new;end;$$;
create trigger fail_waitlist_audit before insert on public.audit_logs for each row execute function pg_temp.fail_waitlist_audit();
set local role service_role;
select extensions.throws_ok($$select pg_temp.join_waitlist('audit-failure','three@example.invalid')$$,'P0001',null,'audit failure fails registration');
reset role;
select extensions.is((select count(*) from business_private.product_waitlist_entries where product_id=(select id from target)),2::bigint,'failed audit creates no partial subscriber');
drop trigger fail_waitlist_audit on public.audit_logs;
create function pg_temp.fail_product_budget() returns trigger language plpgsql as $$begin raise exception 'Synthetic rate store failure';end;$$;
create trigger fail_product_budget before insert on business_private.product_waitlist_buckets for each row execute function pg_temp.fail_product_budget();
set local role service_role;
select extensions.throws_ok($$select pg_temp.join_waitlist('store-failure','store@example.invalid')$$,'P0001',null,'unavailable rate store fails closed');
reset role;
select extensions.is((select count(*) from business_private.product_waitlist_entries where product_id=(select id from target)),2::bigint,'store failure creates no subscriber');
select * from extensions.finish();rollback;
